using Godot;
using System;
using System.Globalization;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;

public partial class AudioAnalysisOperations
{
    private static GDScript Renderer()=>GD.Load<GDScript>("res://Workspaces/AudioWorkspace/audio_renderer.gd");
    private static GDScript Effects()=>GD.Load<GDScript>("res://Workspaces/AudioWorkspace/audio_effects.gd");
    private static string Encoder()=>GD.Load<CSharpScript>("res://scripts/actors/core/ActorVideo.cs").Call("executable","ffmpeg").AsString();
    private static string Directory(){string id=ActorData.new_id();string path=ProjectSettings.GlobalizePath("user://audio_workspace/jobs/"+id);DirAccess.MakeDirRecursiveAbsolute(path);return path;}
    private static Settings Execute(string encoder,string[] args,double duration,RefCounted? job){using var process=new AudioEncoderProcessOperations();return process.run(encoder,args,duration,job,0);}
    private static void Remove(string directory)=>Renderer().Call("_remove_owned",directory);
    private static void Finish(Settings result,string directory)=>Renderer().Call("finish_process_files",result,directory);
    public Settings loudness(Variant source,RefCounted? job)
    {
        string encoder=Encoder();if(encoder.Length==0)return Failure("FFmpeg is required for integrated loudness analysis.");string directory=Directory(),path=source.VariantType==Variant.Type.String?ProjectSettings.GlobalizePath(source.AsString()):directory.PathJoin("source.wav");var stream=GD.Load<CSharpScript>("res://scripts/actors/core/ActorAudio.cs").Call("source",source,Variant.From(job)).As<AudioStream>();if(stream==null){Remove(directory);return Failure("Missing or unreadable audio.");}if(source.VariantType!=Variant.Type.String){var wav=stream as AudioStreamWav;bool owns=false;try{if(wav==null){var decoded=Decode(stream,48000,0,-1,300);if(decoded["error"].AsString().Length>0){Remove(directory);return decoded;}using var cache=new AudioSourceCacheOperations();wav=cache.to_wav(decoded["samples"].AsVector2Array(),48000,true);owns=true;}if(wav.SaveToWav(path)!=Error.Ok){Remove(directory);return Failure("Could not create the temporary analysis source.");}}finally{if(owns)wav?.Dispose();}}var result=Execute(encoder,new[]{"-nostdin","-hide_banner","-v","info","-threads","1","-i",path,"-af","loudnorm=I=-16:TP=-1:LRA=11:print_format=json","-f","null","-"},stream.GetLength(),job);Finish(result,directory);if(!result.TryGetValue("success",out var success)||!success.AsBool())return result;string log=result.TryGetValue("diagnostics",out var diagnostics)?diagnostics.AsString():"";int first=log.LastIndexOf('{'),last=log.LastIndexOf('}');if(first<0||last<first)return Failure("The encoder did not return loudness measurements.");var parsed=Json.ParseString(log.Substring(first,last-first+1));if(parsed.VariantType!=Variant.Type.Dictionary)return Failure("Invalid loudness measurement response.");var values=parsed.AsGodotDictionary();string integrated=values.TryGetValue("input_i",out var inputI)?inputI.ToString():"-inf",peak=values.TryGetValue("input_tp",out var inputTp)?inputTp.ToString():"-inf";double Number(string value)=>value is "-inf" or "inf" or "nan"?-120:double.TryParse(value,NumberStyles.Float,CultureInfo.InvariantCulture,out var number)?number:0;return new Settings {["error"]="",["integrated_lufs"]=Number(integrated),["true_peak_db"]=Number(peak),["loudness_range"]=values.TryGetValue("input_lra",out var lra)?Number(lra.ToString()):0,["silent"]=integrated=="-inf",["method"]="FFmpeg loudnorm / EBU R128"};
    }
    public Settings transform_selection(Vector2[] samples,string operation,int first,int last,double amount,int channel,int rate,RefCounted? job)
    {
        first=Math.Clamp(first,0,samples.Length);last=Math.Clamp(last,first,samples.Length);if(last<=first)return Failure("Select audio to process.");if(operation is not "time_stretch" and not "pitch_shift")return Failure("Unknown time/pitch operation.");if(operation=="time_stretch"&&channel!=-1)return Failure("Choose Stereo for duration-changing edits so the channels remain aligned.");string encoder=Encoder();if(encoder.Length==0)return Failure("FFmpeg is required for sample-selection pitch and time processing.");double factor=operation=="time_stretch"?Math.Clamp(amount,.25,4):1;int count=Math.Max(1,(int)Math.Round((last-first)*factor,MidpointRounding.AwayFromZero));if((long)(samples.Length-(last-first)+count)*8>AudioSourceCacheOperations.MaxDecodeBytes)return Failure("The stretched selection would exceed the 128 MiB working-buffer limit.");string directory=Directory(),input=directory.PathJoin("selection.wav"),output=directory.PathJoin("processed.wav");using var cache=new AudioSourceCacheOperations();using var stream=cache.to_wav(samples[first..last],rate,true);if(stream.SaveToWav(input)!=Error.Ok){Remove(directory);return Failure("Could not prepare the selected audio.");}string filter=Effects().Call("tempo_filter",1/factor).AsString();if(operation=="pitch_shift"){var effect=Effects().Call("create","pitch").AsGodotDictionary();effect["parameters"].AsGodotDictionary()["semitones"]=Math.Clamp(amount,-24,24);filter=Effects().Call("offline_filter",effect,rate).AsString();}filter+=",apad,atrim=end_sample="+count+",asetpts=PTS-STARTPTS";var result=Execute(encoder,new[]{"-nostdin","-hide_banner","-v","error","-threads","1","-i",input,"-af",filter,"-ar",rate.ToString(CultureInfo.InvariantCulture),"-ac","2","-c:a","pcm_s16le","-y",output},(double)count/rate,job);if(!result.TryGetValue("success",out var success)||!success.AsBool()){Finish(result,directory);return result;}using var transformed=AudioStreamWav.LoadFromFile(output);if(transformed==null){Remove(directory);return Failure("Could not decode the processed selection.");}var decoded=cache.decode(transformed,rate,0,-1,300);Remove(directory);if(decoded["error"].AsString().Length>0)return decoded;var segment=decoded["samples"].AsVector2Array();Array.Resize(ref segment,count);if(channel>=0)for(int index=0;index<segment.Length;index++){if(channel==0)segment[index].Y=samples[first+index].Y;else segment[index].X=samples[first+index].X;}int guard=Math.Min(segment.Length/2,Math.Max(1,(int)(rate*.001)));for(int index=0;index<guard;index++){float blend=(float)(index+1)/(guard+1);var left=samples[first+index].Lerp(segment[index],blend);var right=samples[last-1-index].Lerp(segment[segment.Length-1-index],blend);segment[index]=left;segment[segment.Length-1-index]=right;}var merged=new Vector2[samples.Length-(last-first)+count];Array.Copy(samples,merged,first);Array.Copy(segment,0,merged,first,count);Array.Copy(samples,last,merged,first+count,samples.Length-last);return new Settings {["error"]="",["samples"]=merged,["inserted_frames"]=count};
    }
    public Settings noise_profile(AudioStream? stream,double start,double seconds,RefCounted? job)
    {
        if(stream==null||seconds<.05)return Failure("Select at least 50 ms of noise without speech or music.");string encoder=Encoder();if(encoder.Length==0)return Failure("FFmpeg is required for learning a spectral noise profile.");seconds=Math.Min(seconds,10);var decoded=Decode(stream,48000,start,seconds,10);if(decoded["error"].AsString().Length>0)return decoded;var samples=decoded["samples"].AsVector2Array();if(samples.Length<2400)return Failure("The selected noise region is too short.");double sum=0;foreach(var value in samples)sum+=value.LengthSquared()*.5;double rms=Math.Sqrt(sum/samples.Length);if(rms<.000001)return Failure("The selected region is effectively silent; there is no usable noise profile.");double measured=(double)samples.Length/48000;Array.Resize(ref samples,samples.Length+4800);string directory=Directory(),path=directory.PathJoin("noise.wav");using var cache=new AudioSourceCacheOperations();using var wav=cache.to_wav(samples,48000,true);if(wav.SaveToWav(path)!=Error.Ok){Remove(directory);return Failure("Could not prepare the noise selection.");}string filter="asendcmd=c='0 afftdn sn start;"+Effects().Call("number",measured).AsString()+" afftdn sn stop',afftdn";var result=Execute(encoder,new[]{"-nostdin","-hide_banner","-v","info","-threads","1","-i",path,"-af",filter,"-f","null","-"},measured,job);Finish(result,directory);if(!result.TryGetValue("success",out var success)||!success.AsBool())return result;var profiles=new List<double[]>();string log=result.TryGetValue("diagnostics",out var diagnostic)?diagnostic.AsString():"";foreach(string line in log.Split('\n')){int index=line.IndexOf("bn=",StringComparison.Ordinal);if(index<0)continue;var values=new List<double>();foreach(string text in line[(index+3)..].Split(' ',StringSplitOptions.RemoveEmptyEntries))if(double.TryParse(text,NumberStyles.Float,CultureInfo.InvariantCulture,out var value))values.Add(Math.Clamp(value,-24,24));if(values.Count==15)profiles.Add(values.ToArray());}if(profiles.Count==0)return Failure("This FFmpeg build did not return a learned spectral noise profile.");var bands=new GArray();for(int index=0;index<15;index++){double value=0;foreach(var profile in profiles)value+=profile[index];bands.Add(value/profiles.Count);}double db=Mathf.LinearToDb(rms);return new Settings {["error"]="",["noise_profile"]=bands,["floor"]=Math.Clamp(db,-80,-20),["rms_db"]=db,["seconds"]=measured,["start"]=start};
    }
}
